+func (s *Store) DeleteAuthInfo(ctx context.Context, cmd *login.DeleteAuthInfoCommand) error {
+	ctx, span := s.tracer.Start(ctx, "authinfo.k8s.DeleteAuthInfo")
+	defer span.End()
+
+	if cmd == nil {
+		return errors.New("command is nil")
+	}
+
+	authClient, userClient, namespace, err := s.clients(ctx)
+	if err != nil {
+		return err
+	}
+
+	userID := cmd.UserId
+	authModule := cmd.AuthModule
+	userUID := cmd.UserUID
+	if cmd.UserAuth != nil {
+		if userID == 0 {
+			userID = cmd.UserAuth.UserId
+		}
+		if authModule == "" {
+			authModule = cmd.UserAuth.AuthModule
+		}
+		if userUID == "" {
+			userUID = cmd.UserAuth.UserUID
+		}
+	}
+
+	if authModule == "" {
+		return errors.New("auth module is required")
+	}
+
+	if userUID == "" {
+		if userID == 0 {
+			return errors.New("user ID or user UID is required")
+		}
+		userUID, err = s.userUID(ctx, userClient, namespace, userID)
+		if err != nil {
+			if errors.Is(err, user.ErrUserNotFound) {
+				return nil
+			}
+			return err
+		}
+	}
+
+	name := iamv0alpha1.EncodeName(userUID, authModule)
+	err = authClient.Delete(ctx, resource.Identifier{Namespace: namespace, Name: name}, resource.DeleteOptions{})
+	if err != nil && !apierrors.IsNotFound(err) {
+		return err
+	}
+	return nil
